/* @lc app=leetcode id=2203 lang=kotlin */ class Solution { fun dj(n: Int, g: Map<Int, List<Pair<Int, Int>>>, s: Int): LongArray = LongArray(n) { Long.MAX_VALUE / 4 }.also { it[s] = 0 }.let { d -> java.util.PriorityQueue<Pair<Long, Int>>(compareBy<Pair<Long, Int>> { it.first }).also { it.add(0L to s) }.let { pq -> generateSequence { pq.poll() }.filter { (c, u) -> c == d[u] }.forEach { (c, u) -> g[u].orEmpty().forEach { (v, w) -> if (c + w < d[v]) pq.add(c + w to v).also { d[v] = c + w } } }.let { d } } } fun minimumWeight(n: Int, edges: Array<IntArray>, src1: Int, src2: Int, dest: Int): Long = edges.groupBy({ it[0] }, { it[1] to it[2] }).let { g -> edges.groupBy({ it[1] }, { it[0] to it[2] }).let { rg -> dj(n, g, src1).let { a -> dj(n, g, src2).let { b -> dj(n, rg, dest).let { c -> (0 until n).minOf { a[it] + b[it] + c[it] }.let { if (it >= Long.MAX_VALUE / 4) -1L else it } } } } } } }